// Domaines "grand public" : le domaine ne identifie pas le client, on utilise
// l'adresse complete comme cle client (ex: deux TPE distinctes sur gmail.test)
const GRAND_PUBLIC = [
  'gmail.test', 'wanadoo.test', 'hotmail.test', 'outlook.test', 'yahoo.test',
  'gmail.com', 'wanadoo.fr', 'hotmail.com', 'hotmail.fr', 'outlook.com',
  'outlook.fr', 'yahoo.com', 'yahoo.fr', 'orange.fr', 'free.fr', 'laposte.net',
  'icloud.com',
];

// Expediteurs automatiques : on ne cree ni client ni fiche mail
const NO_REPLY = /^(no[-_.]?reply|do[-_.]?not[-_.]?reply|mailer-daemon|postmaster|bounces?)/;

// Garde le message utile : retire les citations (">"), les "Le ... a ecrit :",
// les blocs "Message d'origine" / "Original Message", les en-tetes De/Envoye
// et la signature ("-- "). Si tout est retire, on garde le texte brut.
function corpsUtile(brut) {
  const lignes = String(brut || '').replace(/\r\n?/g, '\n').split('\n');
  const garde = [];
  for (let i = 0; i < lignes.length; i++) {
    const l = lignes[i];
    const s = l.trim();
    if (s.startsWith('>')) continue;
    if (/^(le|on)\s.+(a écrit|wrote)\s*:?\s*$/i.test(s)) break;
    if (/^-{2,}\s*(message d'origine|message initial|original message|forwarded message|message transféré)/i.test(s)) break;
    if (/^(de|from)\s*:\s*\S/i.test(s) && /^(envoy[ée]|sent|date|à|to|objet|subject)\s*:/i.test((lignes[i + 1] || '').trim())) break;
    if (/^-- ?$/.test(l)) break;
    garde.push(l);
  }
  const utile = garde.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  return utile || String(brut || '').trim();
}

const sortie = [];
for (const item of $input.all()) {
  const fromRaw = item.json.from;
  let emailAddress = '';
  let nomAffiche = '';
  if (fromRaw && typeof fromRaw === 'object' && fromRaw.value && fromRaw.value[0]) {
    emailAddress = fromRaw.value[0].address || '';
    nomAffiche = fromRaw.value[0].name || '';
  } else if (typeof fromRaw === 'string') {
    const match = fromRaw.match(/<([^>]+)>/);
    emailAddress = match ? match[1] : fromRaw;
    nomAffiche = fromRaw.replace(/<[^>]*>/, '').replace(/["']/g, '').trim();
  }
  const bracketed = emailAddress.match(/<([^>]+)>/);
  if (bracketed) emailAddress = bracketed[1];
  emailAddress = emailAddress.trim().toLowerCase();

  const atIndex = emailAddress.lastIndexOf('@');
  const domaine = atIndex > -1 && atIndex < emailAddress.length - 1
    ? emailAddress.slice(atIndex + 1).replace(/[^a-z0-9.-]/g, '') || 'inconnu'
    : 'inconnu';
  const local = atIndex > -1 ? emailAddress.slice(0, atIndex) : emailAddress;
  const sujet = item.json.subject || '(sans sujet)';

  // no-reply : adresse, sujet "[AUTO]" ou en-tete Auto-Submitted
  const entetes = item.json.headers || {};
  const autoSubmitted = String(entetes['auto-submitted'] || '').toLowerCase();
  const automatique = NO_REPLY.test(local)
    || /^\s*\[auto\]/i.test(sujet)
    || (autoSubmitted !== '' && autoSubmitted !== 'no');
  if (automatique) continue;

  const particulier = GRAND_PUBLIC.includes(domaine);
  const cleClient = particulier
    ? emailAddress.replace(/[^a-z0-9.@_+-]/g, '') || 'inconnu'
    : domaine;
  const nomClient = particulier ? (nomAffiche || cleClient) : domaine;

  sortie.push({
    json: {
      expediteur: emailAddress || 'inconnu@inconnu.local',
      domaine,
      cleClient,
      nomClient,
      sujet,
      date: item.json.date || new Date().toISOString(),
      corps: corpsUtile(item.json.textPlain || item.json.text || ''),
      messageId: item.json.messageId || item.json['message-id'] || '',
    },
  });
}
return sortie;

