const created = $input.first().json;
const emailData = $('Un mail à la fois').first().json;
return [{
  json: {
    clientId: created.id,
    domaine: emailData.domaine,
  },
}];

const clientInfo = $input.first().json;
const emailData = $('Un mail à la fois').first().json;

return [{
  json: {
    'Sujet': emailData.sujet,
    'Expéditeur': emailData.expediteur,
    'Date': emailData.date,
    'Corps': emailData.corps,
    'Message-ID': emailData.messageId,
    'Statut traitement': 'Nouveau',
    'Client': [clientInfo.clientId],
  },
}];

const results = $input.all();
const emailData = $('Un mail à la fois').first().json;
const estDoublon = !!emailData.messageId && results.length > 0 && !!results[0].json.id;

return [{
  json: {
    estDoublon,
    messageId: emailData.messageId,
    mailExistantId: estDoublon ? results[0].json.id : null,
  },
}];
